def row(n, file, kind, title, citation, image_url, source_page, page_fig, date, credit, lic, shows, struct, state, used, how, linked, pend, what, affected, annotated=()):
    return dict(id='%s-img-%02d' % (SL, n), file=SH + file if not file.startswith(('07_', '03_')) else file, annotated_files=[SH + a if not a.startswith('07_') else a for a in annotated], kind=kind, title=title, citation=citation,
                image_url=image_url, source_page=source_page, page_or_figure=page_fig, image_date=date, credit=credit, license=lic, retrieved='2026-10-10', shows=shows, structure_visible=struct,
                state_shown=state, used_for=used, how_used=how, linked_records=linked, rights_note=RIGHTS, display=True,
                for_3d_check=dict(pending=pend, what_to_check=what, model_values_affected=affected), added_by=BY)
