# A1 / A3 are annotated_files of img-16 / img-14 (not separate rows)
new = [r for r in R if r['id'] not in have]
for r in new:
    p = os.path.join(ROOT, r['file'])
    if not os.path.exists(p): print('MISSING FILE', r['file']); continue
    b = open(p, 'rb').read(); r['bytes'] = len(b); r['sha256'] = hashlib.sha256(b).hexdigest()
    try: r['px'] = list(Image.open(p).size)
    except Exception: r['px'] = None
    rows.append(r)
json.dump(rows, open(os.path.join(REG, 'images.json'), 'w', encoding='utf-8'), indent=1, ensure_ascii=False)
md = open(os.path.join(REG, 'IMAGES.md'), encoding='utf-8').read()
log = open(os.path.join(ROOT, '03_images', 'reefs', 'NEW_IMAGES_LOG.md'), encoding='utf-8').read()
add_md = ''; add_log = ''
for r in new:
    if 'bytes' not in r: continue
    add_md += '\n\n## %s - %s\n- **file**: %s\n- **kind**: %s\n- **shows**: %s\n- **state**: %s\n- **image date**: %s\n- **citation**: %s\n- **image URL**: %s\n- **source page**: %s\n- **page / figure**: %s\n- **credit**: %s\n- **licence**: %s\n- **retrieved**: %s\n- **used for**: %s\n- **How used for the model**: %s\n- **annotated versions**: %s\n- **3D check**: pending %s - %s\n- **size**: %.2f MB, %s px\n- **sha256**: %s\n- **rights**: %s\n- **display in HTML**: True\n- **added by**: %s\n' % (
        r['id'], r['title'], r['file'], r['kind'], r['shows'], r['state_shown'], r['image_date'], r['citation'], r['image_url'], r['source_page'], r['page_or_figure'], r['credit'], r['license'], r['retrieved'], ', '.join(r['used_for']), r['how_used'], ', '.join(r['annotated_files']) or '-', r['for_3d_check']['pending'], r['for_3d_check']['what_to_check'], r['bytes'] / 1e6, r['px'], r['sha256'], r['rights_note'], r['added_by'])
    add_log += '2026-10-10 | %s | %s | %s | %s | %s | %s\n' % (SL, r['id'], r['file'], r['shows'][:110], r['for_3d_check']['what_to_check'][:80], BY)
open(os.path.join(REG, 'IMAGES.md'), 'a', encoding='utf-8').write(add_md)
open(os.path.join(ROOT, '03_images', 'reefs', 'NEW_IMAGES_LOG.md'), 'a', encoding='utf-8').write(add_log)
print('registered', [r['id'] for r in new])
